contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: try a transfer and observe whether it reverts and public state
    function run(address to, uint256 value) public payable {
        require(true);
        // record sender (this contract) balance in c before
        uint256 beforeFrom = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeTo = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        // attempt transfer from this contract to `to` with value `value`
        bool ok = c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            // ok should be true when transfer succeeded per implementation
            // read after-values to include in final assert
        }

        uint256 afterFrom = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterTo = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;

        // General rule:
        // - If the call reverted, then nothing about balances/totalSupply is required here (implementation may revert for many reasons).
        // - If it did not revert, then destination must not be zero address, totalSupply unchanged, sender and receiver balances changed by exactly value.
        assert(reverted || (to != address(0) && afterTotal == beforeTotal && afterFrom + value == beforeFrom && afterTo == beforeTo + value));
    }

    receive() external payable { }
}

